mkdir -p internal/auth && cat > internal/auth/password.go <<'EOF'
// Package auth provides password hashing helpers.
package auth

import (
	"errors"

	"golang.org/x/crypto/bcrypt"
)

// Cost is the bcrypt work factor used for new hashes.
const Cost = 12

// ErrMismatch is returned when a password does not match its hash.
var ErrMismatch = errors.New("auth: password does not match")

// HashPassword returns a bcrypt hash of password.
// bcrypt only uses the first 72 bytes; longer inputs return an error.
func HashPassword(password string) (string, error) {
	h, err := bcrypt.GenerateFromPassword([]byte(password), Cost)
	if err != nil {
		return "", err
	}
	return string(h), nil
}

// CheckPassword reports whether password matches hash.
func CheckPassword(hash, password string) error {
	err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(password))
	if errors.Is(err, bcrypt.ErrMismatchedHashAndPassword) {
		return ErrMismatch
	}
	return err
}
EOF
cat > internal/auth/password_test.go <<'EOF'
package auth

import (
	"errors"
	"testing"
)

func TestHashAndCheck(t *testing.T) {
	hash, err := HashPassword("correct horse battery staple")
	if err != nil {
		t.Fatal(err)
	}
	if err := CheckPassword(hash, "correct horse battery staple"); err != nil {
		t.Fatalf("expected match, got %v", err)
	}
	if err := CheckPassword(hash, "wrong"); !errors.Is(err, ErrMismatch) {
		t.Fatalf("expected ErrMismatch, got %v", err)
	}
}
EOF
cat > main.go <<'EOF'
package main

import (
	"fmt"
	"log"

	"example.com/app/internal/auth"
)

func main() {
	hash, err := auth.HashPassword("s3cret")
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("hash:", hash)
	fmt.Println("match:", auth.CheckPassword(hash, "s3cret") == nil)
}
EOF
cat > .gitignore <<'EOF'
/app
*.test
*.out
EOF
go mod tidy && go vet ./... && go test ./... && go run . && cat go.mod

